import{_ as t,o as d,c as o,a2 as a}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"検索構文","description":"","frontmatter":{},"headers":[],"relativePath":"ja-JP/user-guide/search-syntax.md","filePath":"ja-JP/user-guide/search-syntax.md","lastUpdated":1788596486000}'),c={name:"ja-JP/user-guide/search-syntax.md"};function l(s,e,i,n,r,p){return d(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="検索構文" tabindex="-1">検索構文 <a class="header-anchor" href="#検索構文" aria-label="Permalink to &quot;検索構文&quot;">​</a></h1><p>Lertaro の検索ボックスは、単なる文字列の一致検索にとどまりません。超高速な検索アルゴリズムを搭載し、あいまいな文字飛び一致、論理演算子、単語境界修飾子、ドライブやパスの絞り込み、クエリトークンによる二次フィルター、多言語スマートエイリアスに対応しており、すべての構文を同一のクエリ内で自由に組み合わせて使用できます。</p><h2 id="_1-基本一致モードと大文字小文字の区別" tabindex="-1">1. 基本一致モードと大文字小文字の区別 <a class="header-anchor" href="#_1-基本一致モードと大文字小文字の区別" aria-label="Permalink to &quot;1. 基本一致モードと大文字小文字の区別&quot;">​</a></h2><h3 id="あいまい検索-既定" tabindex="-1">あいまい検索（既定） <a class="header-anchor" href="#あいまい検索-既定" aria-label="Permalink to &quot;あいまい検索（既定）&quot;">​</a></h3><p>Lertaro では既定であいまい一致（Fuzzy Matching）が有効になっています。検索語の任意の文字を順番どおりに入力するだけで、ファイル名やフォルダー名の中で文字が離れていても正確にヒットします。</p><table tabindex="0"><thead><tr><th style="text-align:left;">入力例</th><th style="text-align:left;">一致結果の例</th><th style="text-align:left;">説明</th></tr></thead><tbody><tr><td style="text-align:left;"><code>ltro</code></td><td style="text-align:left;"><code>Lertaro.exe</code></td><td style="text-align:left;"><code>l</code> → <code>t</code> → <code>r</code> → <code>o</code> の順序で飛び飛びに一致（<strong>L</strong>er<strong>t</strong>a<strong>ro</strong>.exe）</td></tr><tr><td style="text-align:left;"><code>vsc</code></td><td style="text-align:left;"><code>Visual Studio Code.lnk</code></td><td style="text-align:left;">各単語の頭文字に一致（<strong>V</strong>isual <strong>S</strong>tudio <strong>C</strong>ode）</td></tr><tr><td style="text-align:left;"><code>rt-fin</code></td><td style="text-align:left;"><code>Q3-report-final.docx</code></td><td style="text-align:left;">連続する部分文字列に一致（Q3-repo<strong>rt-fin</strong>al.docx）</td></tr></tbody></table><p><strong>設定 → 一般 → システム → あいまい一致を有効化</strong> をオフにすると、通常の検索語（演算子なし）は連続した部分文字列として一致する必要があります（<code>abc</code> は <code>a-b-c</code> に一致しなくなります）。この設定は修飾子のない通常の検索語にのみ影響し、後述するすべての演算子の動作は変わりません。</p><h3 id="スマートな大文字小文字の区別-smart-case" tabindex="-1">スマートな大文字小文字の区別（Smart Case） <a class="header-anchor" href="#スマートな大文字小文字の区別-smart-case" aria-label="Permalink to &quot;スマートな大文字小文字の区別（Smart Case）&quot;">​</a></h3><ul><li><strong>すべて小文字の検索</strong>：既定で大文字と小文字を区別しません。例えば <code>myfile</code> は <code>myfile</code>、<code>MyFile</code>、<code>MYFILE</code> などに一致します。</li><li><strong>大文字が含まれる検索</strong>：検索語に大文字が 1 つでも含まれている場合、その単語は自動的に<strong>大文字小文字を区別</strong>するようになります。例えば <code>MyFile</code> は <code>MyFile</code> のみに一致し、小文字の <code>myfile</code> には一致しません。</li></ul><h2 id="_2-複数キーワードと論理演算" tabindex="-1">2. 複数キーワードと論理演算 <a class="header-anchor" href="#_2-複数キーワードと論理演算" aria-label="Permalink to &quot;2. 複数キーワードと論理演算&quot;">​</a></h2><h3 id="スペース-and-論理積" tabindex="-1">スペース：AND（論理積） <a class="header-anchor" href="#スペース-and-論理積" aria-label="Permalink to &quot;スペース：AND（論理積）&quot;">​</a></h3><p>複数の検索語をスペースで区切ると、すべての条件を満たす必要があります。ファイル名内に出現する順序は<strong>問いません</strong>。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report final 2024</span></span></code></pre></div><p>上記の入力は、<code>2024-Q3-report-final.docx</code> と <code>final_report_2024.pdf</code> の両方に一致します。</p><h3 id="パイプ-or-論理和" tabindex="-1">パイプ <code>|</code>：OR（論理和） <a class="header-anchor" href="#パイプ-or-論理和" aria-label="Permalink to &quot;パイプ `|`：OR（論理和）&quot;">​</a></h3><p>パイプ記号 <code>|</code> でキーワードを区切ると、いずれかの条件に一致すればヒットします。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>png | jpg | gif</span></span></code></pre></div><p>AND と OR を自由に組み合わせることができます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report | summary 2024</span></span></code></pre></div><p>これは <code>report</code> または <code>summary</code> を含み、かつ <code>2024</code> も含むファイルを検索します。OR 検索では、条件を満たしたすべてのキーワードが結果の名前の中で同時にハイライト表示されます。</p><h3 id="演算子の優先順位-or-は-and-より優先" tabindex="-1">演算子の優先順位：OR は AND より優先 <a class="header-anchor" href="#演算子の優先順位-or-は-and-より優先" aria-label="Permalink to &quot;演算子の優先順位：OR は AND より優先&quot;">​</a></h3><p>スペース（AND）とパイプ <code>|</code>（OR）を 1 つのクエリ内で混在させる場合、<code>|</code> の優先順位はスペース<strong>より高く</strong>なります。<code>|</code> の両側の語が先に 1 つの OR グループにまとめられ、スペースで区切られたグループ同士が AND で結合されます。括弧はサポートされていないため、この結合順序を変更することはできません。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>report | summary 2024 | draft</span></span></code></pre></div><p>これは <code>(report OR summary) AND (2024 OR draft)</code> と同等です。</p><p>注意：<code>|</code> は両側をスペースで区切った独立した語である必要があります。<code>a|b</code> や <code>a |b</code> は OR として解析されません。また、<code>!</code> の除外語を <code>|</code> の OR グループ内に入れないでください（例: <code>b | !c</code>）。これは「b が一致、または c が一致しない」と解析されます。語を全体から除外したい場合は、スペースで区切った独立した AND 条件として指定してください（例: <code>b !c</code>）。</p><h3 id="単語内のスペースとフレーズの引用符" tabindex="-1">単語内のスペースとフレーズの引用符 <a class="header-anchor" href="#単語内のスペースとフレーズの引用符" aria-label="Permalink to &quot;単語内のスペースとフレーズの引用符&quot;">​</a></h3><p>スペースを含むフレーズを 1 つの単語として検索したい場合は、バックスラッシュでスペースをエスケープ（<code>\\ </code>）するか、単一引用符 <code>&#39;...&#39;</code> または二重引用符 <code>&quot;...&quot;</code> で囲みます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>final\\ report</span></span>\n<span class="line"><span>&#39;final report&#39;</span></span></code></pre></div><p>どちらの書き方も、2 つの独立した AND キーワードではなく、スペースを含んだ 1 つの完全なフレーズとして <code>final report</code> を検索します。</p><h3 id="複数行テキストの貼り付け-自動で-or-に折りたたみ" tabindex="-1">複数行テキストの貼り付け（自動で OR に折りたたみ） <a class="header-anchor" href="#複数行テキストの貼り付け-自動で-or-に折りたたみ" aria-label="Permalink to &quot;複数行テキストの貼り付け（自動で OR に折りたたみ）&quot;">​</a></h3><p>スプレッドシートやテキストファイル、ログなどから複数行のテキスト（1 行に 1 ファイル名）をコピーして検索ボックスに直接貼り付けると、Lertaro は各行を <code>|</code> で連結し、1 つの OR クエリとして自動的に折りたたみます（空白行はスキップされます）。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123</span></span>\n<span class="line"><span>456</span></span>\n<span class="line"><span>678</span></span></code></pre></div><p>貼り付けると次のように自動変換されます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>123 | 456 | 678</span></span></code></pre></div><h2 id="_3-検索演算子一覧" tabindex="-1">3. 検索演算子一覧 <a class="header-anchor" href="#_3-検索演算子一覧" aria-label="Permalink to &quot;3. 検索演算子一覧&quot;">​</a></h2><h3 id="演算子クイックリファレンス" tabindex="-1">演算子クイックリファレンス <a class="header-anchor" href="#演算子クイックリファレンス" aria-label="Permalink to &quot;演算子クイックリファレンス&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">演算子 / 構文</th><th style="text-align:left;">タイプ</th><th style="text-align:left;">効果</th><th style="text-align:left;">入力例</th><th style="text-align:left;">一致結果の例</th></tr></thead><tbody><tr><td style="text-align:left;"><em>(なし)</em></td><td style="text-align:left;">既定のあいまい一致</td><td style="text-align:left;">文字が順番どおりに含まれていれば一致（あいまい検索オン時）</td><td style="text-align:left;"><code>report</code></td><td style="text-align:left;"><code>Q3-report-final.docx</code></td></tr><tr><td style="text-align:left;"><code>!</code></td><td style="text-align:left;">除外</td><td style="text-align:left;">名前に対象の文字列が正確に含まれる項目をすべて除外</td><td style="text-align:left;"><code>!temp</code></td><td style="text-align:left;"><code>temp</code> を含むファイルを除外</td></tr><tr><td style="text-align:left;"><code>&#39;</code></td><td style="text-align:left;">完全一致の反転</td><td style="text-align:left;">あいまいオン時は完全一致へ、オフ時はあいまい一致へ切り替え</td><td style="text-align:left;"><code>&#39;report</code></td><td style="text-align:left;">連続する部分文字列 <code>report</code> が必須</td></tr><tr><td style="text-align:left;"><code>&#39;...&#39;</code></td><td style="text-align:left;">単語境界一致</td><td style="text-align:left;">単語の境界に位置する完全一致（単語内部の誤一致を防止）</td><td style="text-align:left;"><code>&#39;app&#39;</code></td><td style="text-align:left;"><code>app.exe</code> や <code>my-app.log</code> に一致、<code>whatsapp.exe</code> には不一致</td></tr><tr><td style="text-align:left;"><code>^</code></td><td style="text-align:left;">前方一致</td><td style="text-align:left;">ファイル名/フォルダー名が指定の文字で始まる</td><td style="text-align:left;"><code>^IMG</code></td><td style="text-align:left;"><code>IMG_20240101.jpg</code>（<code>MY_IMG.jpg</code> には不一致）</td></tr><tr><td style="text-align:left;"><code>$</code></td><td style="text-align:left;">後方一致</td><td style="text-align:left;">ファイル名/フォルダー名が指定の文字で終わる</td><td style="text-align:left;"><code>.pdf$</code></td><td style="text-align:left;"><code>document.pdf</code>（<code>document.pdf.bak</code> には不一致）</td></tr><tr><td style="text-align:left;"><code>^...$</code></td><td style="text-align:left;">完全一致</td><td style="text-align:left;">名前全体が指定の文字列と完全に一致</td><td style="text-align:left;"><code>^readme.md$</code></td><td style="text-align:left;"><code>readme.md</code> のみに一致</td></tr><tr><td style="text-align:left;"><code>|</code></td><td style="text-align:left;">OR（論理和）</td><td style="text-align:left;">パイプのいずれかの側の条件に一致</td><td style="text-align:left;"><code>doc | pdf</code></td><td style="text-align:left;"><code>doc</code> または <code>pdf</code> を含む名前に一致</td></tr></tbody></table><h3 id="演算子の詳細説明と組み合わせ実例" tabindex="-1">演算子の詳細説明と組み合わせ実例 <a class="header-anchor" href="#演算子の詳細説明と組み合わせ実例" aria-label="Permalink to &quot;演算子の詳細説明と組み合わせ実例&quot;">​</a></h3><ol><li><strong>除外修飾子 <code>!</code></strong>：<code>!term</code> は <code>term</code> という部分文字列を含む結果を完全に除外します。不要な除外を防ぐため、除外語句にはピンイン展開などのエイリアスは適用されません。</li><li><strong>完全一致の反転 <code>&#39;</code></strong>：全体であいまい一致が有効なとき、先頭に <code>&#39;</code> を付けると特定の検索語のみを一時的に完全一致（連続した部分文字列）にできます。 <ul><li>例えば <code>lertaro &#39;v1.2</code> と入力すると、<code>lertaro</code> はあいまい一致、<code>v1.2</code> は連続一致になります。</li><li>完全一致にしていても、ピンインエイリアスを持つファイル名には一致します。例えば <code>&#39;exe$</code> は <code>古恩希尔</code>（ピンインが <code>gexe</code> にマッピングされる）も見つけます。</li></ul></li><li><strong>単語境界一致 <code>&#39;...&#39;</code></strong>：単語を引用符で囲むと（例: <code>&#39;app&#39;</code>）、前後の境界（空白、記号、ハイフン、アンダースコア、文字列の端）をチェックし、長い単語の途中への意図しない一致を防ぎます。</li><li><strong>完全一致 <code>^...$</code></strong>：<code>^</code> と <code>$</code> が<strong>同一の単語</strong>を囲んでいる場合にのみ機能します。別々の単語に指定した場合（例: <code>^src md$</code>）は、それぞれ独立した前方一致と後方一致として扱われます。</li></ol><p><strong>複数演算子の組み合わせ例</strong>：</p><ul><li><code>^IMG !.png$ 2024</code>：<code>IMG</code> で始まり、<code>2024</code> を含み、拡張子が <code>.png</code> <strong>ではない</strong> ファイルを検索。</li><li><code>&#39;data | &#39;backup ^2024 .zip$</code>：<code>2024</code> で始まり、<code>.zip</code> で終わり、かつ名前に <code>data</code> または <code>backup</code> が正確に含まれるアーカイブを検索。</li><li><code>^report &#39;公告 | &#39;gw .pdf$ !draft</code>：<code>report</code> で始まり、<code>.pdf</code> で終わり、<code>draft</code> を含まず、名前に <code>公告</code>、<code>gw</code>、<code>公文</code>、または <code>gw</code> のピンインに一致するその他の文字列が正確に含まれるファイルを検索します（<code>&#39;公告 | &#39;gw</code> が 1 つの OR グループを構成し、残りのスペース区切りの条件とは AND で結合されます）。</li></ul><h2 id="_4-パスモードとドライブの絞り込み" tabindex="-1">4. パスモードとドライブの絞り込み <a class="header-anchor" href="#_4-パスモードとドライブの絞り込み" aria-label="Permalink to &quot;4. パスモードとドライブの絞り込み&quot;">​</a></h2><h3 id="ドライブの指定" tabindex="-1">ドライブの指定 <a class="header-anchor" href="#ドライブの指定" aria-label="Permalink to &quot;ドライブの指定&quot;">​</a></h3><p>検索ボックスの先頭にドライブ文字とコロンを入力すると、検索範囲を特定のドライブに限定できます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d: report</span></span></code></pre></div><p>スペースは省略可能で、<code>d:report</code> と <code>d: report</code> は同等です。</p><h3 id="フルパスモード" tabindex="-1">フルパスモード <a class="header-anchor" href="#フルパスモード" aria-label="Permalink to &quot;フルパスモード&quot;">​</a></h3><p>検索文字列にパス区切り文字（<code>\\</code> または <code>/</code>）が含まれている場合、Lertaro は自動的にフルパス一致モードに切り替わります。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>D:\\Projects\\Lertaro</span></span></code></pre></div><p>末尾をパス区切り文字で終えた場合（例: <code>D:\\Projects\\</code>）、そのフォルダーの<strong>直下および内部</strong>にある項目を検索します。</p><h3 id="親フォルダー名のフォールバック一致-folder-matching" tabindex="-1">親フォルダー名のフォールバック一致（Folder Matching） <a class="header-anchor" href="#親フォルダー名のフォールバック一致-folder-matching" aria-label="Permalink to &quot;親フォルダー名のフォールバック一致（Folder Matching）&quot;">​</a></h3><p>ファイル名単体での検索結果が上限件数に達しない場合、Lertaro は検索語のうちファイル名に一致しなかった部分を使って親フォルダー名との一致を自動的に補完します。特別な構文は不要です。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>d01j dcj</span></span></code></pre></div><p><code>dcj</code> という文字列がファイル名自体に含まれていなくても、<code>dcj</code> という名前（またはエイリアス）のフォルダー内にある <code>d01j.txt</code> を見つけることができます。</p><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>少なくとも 1 つの単語がファイル名自体に一致している必要があり、ファイル名単体での一致で結果が埋まらなかった場合にのみ動作します。補完された結果は常に通常の検索結果の後ろに並び、通常の検索結果の順序を乱すことはありません。</p></div><h2 id="_5-クエリトークンと二次フィルター-query-tokens" tabindex="-1">5. クエリトークンと二次フィルター（Query Tokens） <a class="header-anchor" href="#_5-クエリトークンと二次フィルター-query-tokens" aria-label="Permalink to &quot;5. クエリトークンと二次フィルター（Query Tokens）&quot;">​</a></h2><p>Lertaro では、メインの検索語の後ろにコロン <code>:</code>（<strong>設定 → 一般 → システム → クエリトークン総前置文字</strong> で変更可能）で始まる**クエリトークン（Query Tokens）**を追加し、結果の二次フィルターや並べ替えを行えます。</p><p>1 つの <code>:</code> の後ろにカンマ <code>,</code> で区切って複数のトークンを連結できます（例: <code>report :@doc,M-,:-F</code>）。</p><h3 id="ファイルカテゴリフィルター-カテゴリ名" tabindex="-1">ファイルカテゴリフィルター（<code>:@&lt;カテゴリ名&gt;</code>） <a class="header-anchor" href="#ファイルカテゴリフィルター-カテゴリ名" aria-label="Permalink to &quot;ファイルカテゴリフィルター（`:@&lt;カテゴリ名&gt;`）&quot;">​</a></h3><p>定義済みの拡張子カテゴリを素早く適用できます。<code>|</code> による複数指定も可能です。</p><ul><li><code>:@doc</code>：ドキュメント類（<code>*.doc; *.docx; *.pdf; *.txt; *.ppt; *.pptx; *.xls; *.xlsx; *.csv; *.rtf; *.md; *.wps</code>）</li><li><code>:@img</code>：画像類（<code>*.jpg; *.jpeg; *.png; *.gif; *.bmp; *.webp; *.ico; *.svg; *.tif; *.tiff; *.psd; *.ai</code>）</li><li><code>:@video</code>：動画類（<code>*.mp4; *.mkv; *.avi; *.mov; *.wmv; *.flv; *.m4v; *.webm; *.3gp; *.rmvb; *.ts</code>）</li><li><code>:@audio</code>：音声類（<code>*.mp3; *.wav; *.flac; *.aac; *.ogg; *.m4a; *.wma; *.ape</code>）</li><li><code>:@zip</code>：圧縮ファイル類（<code>*.zip; *.rar; *.7z; *.tar; *.gz; *.bz2; *.xz; *.iso</code>）</li></ul><p><strong>例</strong>：</p><ul><li><code>財務 :@doc</code>：ドキュメント類から「財務」を検索。</li><li><code>壁紙 :@img</code>：画像ファイルから「壁紙」を検索。</li><li><code>clip :@video|audio</code>：動画または音声ファイルから「clip」を検索。</li></ul><p><strong>設定 → プラグイン → CoreExtensions</strong> でカテゴリのルール編集や新規追加が可能です。</p><p>全体検索ウィンドウ左側の種類フィルターは、同じプラグインの<strong>検索フィルター</strong>設定グループで別途設定します。サイドバーのフィルター名は表示専用です。<code>@キーワード</code> 参照はサイドバーフィルターのルール欄でのみ解析され、無効なものを含む<strong>カスタムフィルター</strong>一覧のキーワードを参照します。</p><h3 id="拡張子の直接指定フィルター-ext-または-ext1-ext2" tabindex="-1">拡張子の直接指定フィルター（<code>:.ext</code> または <code>:.ext1.ext2</code>） <a class="header-anchor" href="#拡張子の直接指定フィルター-ext-または-ext1-ext2" aria-label="Permalink to &quot;拡張子の直接指定フィルター（`:.ext` または `:.ext1.ext2`）&quot;">​</a></h3><p>ドットで始まる拡張子を直接指定します（フォルダーは自動的に除外されます）。</p><ul><li><code>report :.pdf</code>：<code>.pdf</code> ファイルのみに限定。</li><li><code>data :.csv.xlsx</code>：<code>.csv</code> または <code>.xlsx</code> ファイルのみに限定。</li></ul><h3 id="並べ替えとファイル-フォルダーの絞り込み-scmaf" tabindex="-1">並べ替えとファイル/フォルダーの絞り込み（<code>:[SCMAF]</code>） <a class="header-anchor" href="#並べ替えとファイル-フォルダーの絞り込み-scmaf" aria-label="Permalink to &quot;並べ替えとファイル/フォルダーの絞り込み（`:[SCMAF]`）&quot;">​</a></h3><p>1 文字のアルファベットで属性を指定します：<code>S</code>（サイズ）、<code>C</code>（作成日時）、<code>M</code>（更新日時）、<code>A</code>（アクセス日時）、<code>F</code>（フォルダー/ファイルの絞り込み）。</p><p>文字単体は<strong>昇順</strong>（小さい順 / 古い順）を表し、マイナス記号 <code>-</code>（プレフィックスまたはサフィックス、例: <code>M-</code> や <code>:-M</code>）を付けると<strong>降順</strong>（大きい順 / 新しい順）または反転フィルターになります。</p><table tabindex="0"><thead><tr><th style="text-align:left;">トークン構文</th><th style="text-align:left;">効果</th><th style="text-align:left;">主な使用シナリオ</th></tr></thead><tbody><tr><td style="text-align:left;"><code>:S</code></td><td style="text-align:left;">サイズの昇順（小さいファイルが先頭）</td><td style="text-align:left;">空ファイルや微小ファイルの探索</td></tr><tr><td style="text-align:left;"><code>:S-</code> または <code>:-S</code></td><td style="text-align:left;">サイズの降順（大きいファイルが先頭）</td><td style="text-align:left;"><code>log :S-</code>（容量を圧迫しているログファイルの調査）</td></tr><tr><td style="text-align:left;"><code>:M</code></td><td style="text-align:left;">更新日時の昇順（古いファイルが先頭）</td><td style="text-align:left;">長期間更新されていないファイルの確認</td></tr><tr><td style="text-align:left;"><code>:M-</code> または <code>:-M</code></td><td style="text-align:left;">更新日時の降順（最新の更新が先頭）</td><td style="text-align:left;"><code>report :M-</code>（直近で編集したドキュメントの検索）</td></tr><tr><td style="text-align:left;"><code>:C</code> / <code>:C-</code></td><td style="text-align:left;">作成日時の昇順 / 降順</td><td style="text-align:left;"><code>build :C-</code>（最新のビルド成果物の確認）</td></tr><tr><td style="text-align:left;"><code>:A</code> / <code>:A-</code></td><td style="text-align:left;">アクセス日時の昇順 / 降順</td><td style="text-align:left;"><code>project :A-</code>（最近開いたプロジェクトの検索）</td></tr><tr><td style="text-align:left;"><code>:F</code></td><td style="text-align:left;"><strong>フォルダーのみ</strong>（通常ファイルを除外）</td><td style="text-align:left;"><code>config :F</code>（config という名前のフォルダーのみ検索）</td></tr><tr><td style="text-align:left;"><code>:-F</code> または <code>:F-</code></td><td style="text-align:left;"><strong>ファイルのみ</strong>（フォルダーを除外）</td><td style="text-align:left;"><code>config :-F</code>（config という名前のファイルのみ検索）</td></tr></tbody></table><h3 id="ワイルドカードによる二次フィルター-式-または-式" tabindex="-1">ワイルドカードによる二次フィルター（<code>:?&lt;式&gt;</code> または <code>?&lt;式&gt;</code>） <a class="header-anchor" href="#ワイルドカードによる二次フィルター-式-または-式" aria-label="Permalink to &quot;ワイルドカードによる二次フィルター（`:?&lt;式&gt;` または `?&lt;式&gt;`）&quot;">​</a></h3><p>標準的な Windows ワイルドカード（<code>?</code> は任意の 1 文字、<code>*</code> は任意の文字列）を使用して結果を絞り込みます。<code>|</code> や <code>;</code> で複数の OR 条件を指定できます。</p><ul><li><code>mp4 :?(2026???????????)</code>：<code>2026</code> とそれに続く 11 桁のタイムスタンプを含む動画に一致。</li><li><code>photo :?IMG_????.jpg|DSC_????.jpg</code>：特定の形式の写真番号に一致。</li></ul><h3 id="パス文字列による二次フィルター-パス式" tabindex="-1">パス文字列による二次フィルター（<code>::&lt;パス式&gt;</code>） <a class="header-anchor" href="#パス文字列による二次フィルター-パス式" aria-label="Permalink to &quot;パス文字列による二次フィルター（`::&lt;パス式&gt;`）&quot;">​</a></h3><p>結果の親フォルダー階層またはファイル名自体に、指定されたあいまいキーワードが含まれていることを要求します。</p><ul><li><code>report ::2024</code>：ファイルが存在するパスのどこかに <code>2024</code> が含まれている必要があります。</li><li><code>main ::&quot;src\\core&quot;</code>：<code>src\\core</code> 配下に存在するファイルに限定。</li></ul><h3 id="連結トークンの組み合わせ例" tabindex="-1">連結トークンの組み合わせ例 <a class="header-anchor" href="#連結トークンの組み合わせ例" aria-label="Permalink to &quot;連結トークンの組み合わせ例&quot;">​</a></h3><p>複数のトークンを 1 つの <code>:</code> の後ろに連結して指定できます。</p><ul><li><code>財務レポート :@doc,M-</code>：「財務レポート」を検索し、ドキュメント類に限定し、更新日時の新しい順にソート。</li><li><code>backup :.zip,S-,:-F</code>：「backup」を検索し、<code>.zip</code> 形式に限定し、ファイルサイズが大きい順にソート、ファイルのみを表示。</li><li><code>icon ::assets,?*128*</code>：「icon」を検索し、パスに <code>assets</code> を含み、名前に <code>128</code> が含まれる項目に限定。</li></ul><h2 id="_6-特殊な検索機能" tabindex="-1">6. 特殊な検索機能 <a class="header-anchor" href="#_6-特殊な検索機能" aria-label="Permalink to &quot;6. 特殊な検索機能&quot;">​</a></h2><h3 id="単一検索での除外ルールの一時的なバイパス" tabindex="-1">単一検索での除外ルールの一時的なバイパス <a class="header-anchor" href="#単一検索での除外ルールの一時的なバイパス" aria-label="Permalink to &quot;単一検索での除外ルールの一時的なバイパス&quot;">​</a></h3><p>検索クエリの先頭に <code>*</code> を付けると、<a href="./settings/index-drives.html#除外ルール"><strong>除外ルール</strong></a> で設定したパス除外、Glob、正規表現をその回の検索に限り一時的に無効化して検索できます。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>*node_modules</span></span></code></pre></div><p>先頭の <code>*</code> は検索前に自動で除去され、テキストの一致判定には含まれません。すでにインデックス済みの項目のみが対象となります（ネットワークドライブや WSL で最初からインデックスされていないフォルダーは表示されません）。システムの隠しファイル除外などは維持されます。</p><h3 id="検索結果種別トリガー" tabindex="-1">検索結果種別トリガー <a class="header-anchor" href="#検索結果種別トリガー" aria-label="Permalink to &quot;検索結果種別トリガー&quot;">​</a></h3><p><strong>設定 → 一般 → クイック検索ウィンドウ → 結果タイプ優先度</strong> で、特定の結果タイプ（アプリケーション、システム設定、ファイルカテゴリ、プラグイン項目、ファイルなど）に 1 文字の<strong>トリガー</strong>を割り当てることができます。</p><p>クイック検索バーの先頭にそのトリガー文字を入力すると、そのタイプの結果のみが表示され、他のタイプはすべて非表示になります。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>;vs</span></span></code></pre></div><p>例えば <code>;</code> が「アプリケーション」に割り当てられている場合、上記のように入力するとアプリケーション内の Visual Studio のみが検索されます。クイックウィンドウおよびインラインウィンドウでは、トリガーの有無にかかわらず履歴とお気に入りは常に最上位に固定表示されます。</p><h2 id="_7-多言語スマートエイリアス" tabindex="-1">7. 多言語スマートエイリアス <a class="header-anchor" href="#_7-多言語スマートエイリアス" aria-label="Permalink to &quot;7. 多言語スマートエイリアス&quot;">​</a></h2><h3 id="中国語ファイル名-ピンインエイリアス" tabindex="-1">中国語ファイル名：ピンインエイリアス <a class="header-anchor" href="#中国語ファイル名-ピンインエイリアス" aria-label="Permalink to &quot;中国語ファイル名：ピンインエイリアス&quot;">​</a></h3><p>標準搭載のピンインエイリアスプラグイン（<code>PinyinAlias</code>）により、設定なしでピンイン（ローマ字）による中国語ファイル名の検索が可能です。</p><ul><li><strong>全ピンイン（Full Pinyin）</strong>：<code>chongqing</code> と入力して <code>重庆.docx</code> に一致。</li><li><strong>頭文字（Initials）</strong>：<code>cq</code> と入力しても <code>重庆.docx</code> に一致、<code>wzry</code> で <code>王者荣耀.exe</code> に一致。</li><li><strong>多音字のサポート</strong>：複数の読み方を持つ漢字も自動的にインデックスされます（例: <code>重庆</code> は <code>chongqing</code> と <code>zhongqing</code> の両方でヒット）。</li></ul><p><strong>設定 → プラグイン</strong> で <code>PinyinAlias</code> プラグインの状態を確認できます。</p><h3 id="スペイン語ファイル名-アクセント記号エイリアス" tabindex="-1">スペイン語ファイル名：アクセント記号エイリアス <a class="header-anchor" href="#スペイン語ファイル名-アクセント記号エイリアス" aria-label="Permalink to &quot;スペイン語ファイル名：アクセント記号エイリアス&quot;">​</a></h3><p>標準搭載の <code>SpanishAlias</code> プラグインにより、アクセント記号付き文字（<code>á</code>, <code>é</code>, <code>í</code>, <code>ó</code>, <code>ú</code>, <code>ü</code>, <code>ñ</code>）を含むファイル名を、通常の ASCII 文字でそのまま検索できます。</p><ul><li><code>cancion</code> で <code>Canción.mp3</code> に一致。</li><li><code>nino</code> で <code>Niño.txt</code> に一致。</li><li><code>ciguena</code> で <code>Cigüeña.png</code> に一致。</li></ul><p>一致した文字（元のファイル名に含まれるアクセント記号付き文字を含む）は正確にハイライトされます。</p><h2 id="_8-よくある質問とお気に入り" tabindex="-1">8. よくある質問とお気に入り <a class="header-anchor" href="#_8-よくある質問とお気に入り" aria-label="Permalink to &quot;8. よくある質問とお気に入り&quot;">​</a></h2><h3 id="お気に入り、カスタムエイリアスではない" tabindex="-1">お気に入り、カスタムエイリアスではない <a class="header-anchor" href="#お気に入り、カスタムエイリアスではない" aria-label="Permalink to &quot;お気に入り、カスタムエイリアスではない&quot;">​</a></h3><p>Lertaro には一般的な「カスタム検索エイリアス/マクロ」機能はありません。最も近い代替手段：</p><ul><li><a href="./settings/favorites.html"><strong>お気に入り</strong></a> ：任意のファイル、フォルダー、または URL をカスタム表示名でお気に入りに登録すると、その表示名で直接検索できるようになります（検索結果に ★ アイコンが表示されます）。</li><li><strong>ファイルフィルター</strong>（<a href="./instant-answers.html#ファイルフィルター"><strong>インスタントアンサー</strong></a> を参照）：トリガーキーワードにフォルダーを紐付けると、クイック検索ボックスで <code>キーワード 語</code> と入力するだけで通常のインデックス検索をそれらのフォルダー内に限定できます。</li></ul><p>特定のキーワードで外部プログラムを起動したりスクリプトを実行したい場合は、<a href="./instant-answers.html#カスタムコマンド"><strong>カスタムコマンド</strong></a> を参照してください。</p>',105)])])}const x=t(c,[["render",l]]);export{h as __pageData,x as default};
